package au.aumanet.app;
import android.content.Context;import android.content.pm.ApplicationInfo;import android.net.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.function.*;
/** Explicit per-network HTTPS, or an explicitly pinned debug USB loopback fixture. */
final class NodeUpdateInternet {
 private static final ScheduledThreadPoolExecutor DEADLINES=new ScheduledThreadPoolExecutor(1,r->{Thread t=new Thread(r,"AuMaNET-update-http-deadline");t.setDaemon(true);return t;});static{DEADLINES.setRemoveOnCancelPolicy(true);}private final ConnectivityManager manager;private final boolean debug;private volatile Fixture fixture;
 private static final class Fixture{final int port;final String hash;final long started=android.os.SystemClock.elapsedRealtime();Fixture(int port,String hash){this.port=port;this.hash=hash;}boolean live(){long d=android.os.SystemClock.elapsedRealtime()-started;return d>=0&&d<300000;}}
 private static final class Opened{final HttpURLConnection connection;final Network network;final Fixture fixture;final AtomicBoolean active=new AtomicBoolean(true);ScheduledFuture<?> timeout;Opened(HttpURLConnection c,Network n,Fixture f){connection=c;network=n;fixture=f;}void close(){active.set(false);if(timeout!=null)timeout.cancel(false);connection.disconnect();}}
 NodeUpdateInternet(Context context){manager=(ConnectivityManager)context.getSystemService(Context.CONNECTIVITY_SERVICE);debug=(context.getApplicationInfo().flags&ApplicationInfo.FLAG_DEBUGGABLE)!=0;}
 void fixture(int port,String hash){if(!debug||port<0||port>65535||port>0&&(port<1024||!hash.matches("[a-f0-9]{64}"))||port==0&&!hash.isEmpty())throw new SecurityException();fixture=port==0?null:new Fixture(port,hash);}
 String source(){Fixture f=fixture;return f!=null&&f.live()?"usb-fixture":"https";}
 static boolean valid(NetworkCapabilities c){return c!=null&&c.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)&&c.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)&&!c.hasTransport(NetworkCapabilities.TRANSPORT_VPN);}
 Network selected(Network excluded)throws IOException{if(source().equals("usb-fixture"))return null;Network active=manager.getActiveNetwork();NetworkCapabilities current=active==null?null:manager.getNetworkCapabilities(active);if(current!=null&&current.hasTransport(NetworkCapabilities.TRANSPORT_VPN))throw new IOException("Validated internet unavailable");if(active!=null&&!active.equals(excluded)&&valid(current))return active;for(Network n:manager.getAllNetworks())if(!n.equals(excluded)&&valid(manager.getNetworkCapabilities(n)))return n;throw new IOException("Validated internet unavailable");}
 private boolean live(Opened open){return open.active.get()&&(open.fixture!=null?fixture==open.fixture&&open.fixture.live():open.network!=null&&valid(manager.getNetworkCapabilities(open.network)));}
 private Opened open(Network network,String initial,String fixturePath,BooleanSupplier current,AtomicReference<Closeable> resource)throws Exception{Fixture local=fixture;if(local!=null&&!local.live())local=null;URL url=local==null?NodeReleaseIndex.https(initial):new URL("http://127.0.0.1:"+local.port+fixturePath);for(int redirects=0;redirects<=5;redirects++){if(!current.getAsBoolean()||local==null&&(network==null||!valid(manager.getNetworkCapabilities(network)))||local!=null&&(fixture!=local||!local.live()))throw new IOException();if(local==null)NodeReleaseIndex.https(url.toExternalForm());HttpURLConnection connection=(HttpURLConnection)(local==null?network.openConnection(url):url.openConnection());connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(10000);connection.setReadTimeout(10000);connection.setRequestProperty("Accept-Encoding","identity");Closeable close=connection::disconnect;resource.set(close);Opened result=new Opened(connection,network,local);result.timeout=DEADLINES.schedule(()->{result.active.set(false);connection.disconnect();},fixturePath.equals("/catalog.json")?30000:NodeUpdateCodec.LIMIT_MS,TimeUnit.MILLISECONDS);try{if(!current.getAsBoolean()||!live(result))throw new IOException();int status=connection.getResponseCode();if(status==301||status==302||status==303||status==307||status==308){if(local!=null)throw new SecurityException();String location=connection.getHeaderField("Location");if(location==null)throw new IOException();url=NodeReleaseIndex.https(new URL(url,location).toExternalForm());result.close();resource.compareAndSet(close,null);continue;}if(status!=200)throw new IOException("Signed firmware resource unavailable");return result;}catch(Exception failed){result.close();resource.compareAndSet(close,null);throw failed;}}throw new IOException();}
 byte[] catalog(Network network,BooleanSupplier current,AtomicReference<Closeable> resource)throws Exception{Opened open=open(network,NodeReleaseManifest.CATALOG_URL,"/catalog.json",current,resource);try{byte[] b=NodeUpdateCache.read(open.connection.getInputStream(),NodeReleaseIndex.MAX_BYTES);if(!current.getAsBoolean()||!live(open)||open.fixture!=null&&!NodeReleaseManifest.hash(b).equals(open.fixture.hash))throw new SecurityException();return b;}finally{resource.set(null);open.close();}}
 void download(Network network,NodeReleaseIndex.Release release,File destination,BooleanSupplier current,LongConsumer progress,AtomicReference<Closeable> resource)throws Exception{Opened open=open(network,release.url,"/images/"+release.manifest.imageSha+".bin",current,resource);boolean complete=false;try{long length=open.connection.getContentLengthLong();if(length!=-1&&length!=release.manifest.imageBytes)throw new IOException();MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=open.connection.getInputStream();FileOutputStream out=new FileOutputStream(destination)){byte[] b=new byte[8192];int total=0;for(int n;(n=in.read(b))!=-1;){if(!current.getAsBoolean()||!live(open)||total+n>release.manifest.imageBytes)throw new IOException();hash.update(b,0,n);out.write(b,0,n);total+=n;progress.accept(total);}out.getFD().sync();if(total!=release.manifest.imageBytes||!NodeReleaseManifest.hex(hash.digest()).equals(release.manifest.imageSha)||!current.getAsBoolean()||!live(open))throw new IOException();complete=true;}}finally{resource.set(null);open.close();if(!complete&&destination.exists())destination.delete();}}
}
